CREATE OR REPLACE FUNCTION gx_e1(p VARCHAR2) RETURN VARCHAR2 IS
BEGIN
  IF p IS NULL THEN RETURN 'null'; END IF;
  RETURN 'value';
END;
/
CREATE OR REPLACE FUNCTION gx_e2(p VARCHAR2) RETURN VARCHAR2 IS
BEGIN
  IF p = '' THEN RETURN 'empty'; END IF;
  RETURN 'other';
END;
/
CREATE OR REPLACE FUNCTION gx_e3(a VARCHAR2, b VARCHAR2) RETURN VARCHAR2 IS
BEGIN
  RETURN a || b;
END;
/
CREATE OR REPLACE FUNCTION gx_e4(p VARCHAR2) RETURN NUMBER IS
BEGIN
  RETURN LENGTH(p);
END;
/
CREATE OR REPLACE FUNCTION gx_e5(p VARCHAR2) RETURN VARCHAR2 IS
  v VARCHAR2(10) := '';
BEGIN
  IF v IS NULL THEN RETURN 'v is null'; END IF;
  RETURN 'v is not null';
END;
/
CREATE TABLE gx_notes (id NUMBER, note VARCHAR2(20) DEFAULT '');
CREATE OR REPLACE FUNCTION gx_e6(p VARCHAR2) RETURN VARCHAR2 IS
BEGIN
  RETURN NVL(p, '');
END;
/
